"Скрыть сообщения?":"要屏蔽消息吗？",
"Сообщения Ловчего «{0}» перестанут показываться на этом телефоне. Вернуть можно в любой момент — строкой «Скрытых Ловчих» вверху чата.":"捕灵师“{0}”的消息将不再在这台手机上显示。随时可以恢复——点聊天顶部的“已屏蔽的捕灵师”。",
