"откроется в сезоне {0}":"第{0}赛季开启",
"Клан мифологии следующего сезона. Он откроется, когда Орден соберёт Алатырь-камень и Кощей снова расколет его.":"下一个赛季神话的战队。修会拼好阿拉特尔石、科谢伊再次将它击碎时，这个战队就会开启。",
"Клан можно выбрать с {0} уровня":"{0}级起可以选择战队",
"Выбери клан":"选择战队",
"У каждой мифологии Перепутицы — свой клан Ордена. Кланы держат Святилища: поставь своего духа защитником — и Святилище окрасится цветом твоего клана, а тебе каждый день будет приходить дань. Выбор — навсегда.":"大纠缠中的每种神话都有修会里属于自己的战队。战队守护圣所：派你的精灵去当守卫，圣所就会染上你战队的颜色，你每天都能收到贡品。选择后不能更改。",
"Позже":"以后再说",
"Выбор — навсегда: сменить клан потом нельзя.":"选择后不能更改：之后无法更换战队。",
"Переход бесплатный и единственный. Защитники достоят свой срок в Святилищах прежнего клана, чат — уже нового.":"免费转换，仅此一次。你的守卫会在原战队的圣所上站完这一班，聊天频道则换成新战队的。",
"Мифология: {0}":"神话：{0}",
"Звание: {0}":"称号：{0}",
"На святилищах своей мифологии ({0}) защитники клана собирают дань {1}.":"在本神话的圣所（{0}）上，战队守卫收取{1}贡品。",
"Перейти":"转入",
"Вступить":"加入",
"Ты в «{0}»! Побеждай в Святилищах и ставь защитников.":"你已加入“{0}”！去圣所取胜，派出守卫吧。",
"Теперь ты в «{0}». Добро пожаловать, {1}!":"你已加入“{0}”。欢迎你，{1}！",
"Дружины стали кланами":"亲兵团变成了战队",
"Орден собрал Ловчих всех земель: теперь у каждой мифологии свой клан, а с каждым новым сезоном Алатыря приходит ещё один.":"修会召集了各地的捕灵师：如今每种神话都有自己的战队，而每个新的阿拉特尔赛季还会再来一个。",
"Твоя дружина теперь —":"你的亲兵团现在是",
"Защитники в Святилищах и чат клана остались с тобой.":"你在圣所上的守卫和战队聊天都还在。",
"Один раз можно бесплатно перейти в любой открытый клан. Выбери его — или останься. Перейти можно и позже, на экране клана.":"你可以免费转入任意一个已开启的战队，仅限一次。选一个——或者留下。之后也可以在战队页面转入。",
"Остаться":"留下",
"Кого поставить защитником?":"派谁去当守卫？",
"Дух останется у тебя: в Святилище встанет его отражение. Пока он стоит, раз в день приходит дань — ✦ {0} и оберег.":"精灵仍然归你：站在圣所上的是它的倒影。只要它在岗，每天都会送来贡品——✦ {0}和一个灵符。",
"Отражение стоит до {0} суток: первые {1} ч в полной силе, потом устаёт и слабеет, а затем возвращается домой. Защитники — не больше чем на {2} Святилищах.":"分身最多驻守{0}天：前{1}小时全力以赴，之后疲劳变弱，最后回家。守卫最多驻守{2}座圣所。",
"Это святилище мифологии твоего клана — дань здесь {0}.":"这是你战队所属神话的圣所——这里的贡品{0}。",
"Защитник встал в Святилище «{0}» — оно под знаменем «{1}»":"守卫已进驻圣所“{0}”——它现在飘扬着“{1}”的旗帜",
"Срок на посту вышел — защитники вернулись с {0}. За службу: {1}":"值守期满——守卫从{0}归来。值守奖励：{1}",
