"Дань — ✦ {0}, оберег и {1} {2} в день за каждое Святилище, где твой защитник отстоял хотя бы {3} ч. Защитник стоит до {4} суток и понемногу устаёт; если соперники его победят или срок выйдет, он вернётся с искрами за время на посту. Часть Святилищ — вольные: их не держит ни один клан.":"贡品——每座你的守卫值守满{3}小时的圣所，每天✦ {0}、一个灵符和{1}{2}。守卫最多驻守{4}天，会逐渐疲劳；被对手击败或期满时，会带着值守的火花回来。部分圣所是自由的：不归任何战队。",
