"Здесь сходятся старые дороги Нави, Олимпа, Асгарда и холмов сидов — от Москвы до Дублина.":"纳维、奥林匹斯、阿斯加德与希族山丘的古老道路在此交汇——从莫斯科到都柏林。",
"Азия":"亚洲",
"От Уральских гор до Тихого океана. Отсюда родом небесные драконы Китая, а Сибирь и Средняя Азия — края славянских духов.":"从乌拉尔山脉到太平洋。中国的天龙源于此地，西伯利亚和中亚则是斯拉夫精灵的故乡。",
"Африка":"非洲",
"Здесь, у Нила, стоят врата Дуата — родины египетских богов и духов пустыни.":"在这里，尼罗河畔矗立着杜阿特之门——埃及众神与沙漠精灵的故乡。",
"Северная Америка":"北美洲",
"Земля пернатых змеев: из долины Мехико вышли ацтекские боги и духи.":"羽蛇之地：阿兹特克的神灵与精灵走出了墨西哥谷。",
"Южная Америка":"南美洲",
"Сельва, Анды и Амазонка. Ацтекские духи разлетелись и сюда — до самой Огненной Земли.":"丛林、安第斯山与亚马孙河。阿兹特克精灵也飞散到了这里——一直到火地岛。",
"Австралия и Океания":"澳大利亚和大洋洲",
"Своих мифологий у Ордена здесь пока нет: сюда забредают китайские духи из соседней Юго-Восточной Азии.":"修会在这里还没有本土神话：中国精灵从邻近的东南亚游荡而来。",
"Антарктида":"南极洲",
"Здесь только пингвины и ледяные духи. Врата сюда не открываются — слишком холодно даже для Ловчих.":"这里只有企鹅和冰之精灵。传送门不会通往这里——连捕灵师都嫌太冷。",
"Миров духов всегда было много — у каждого народа свой: Навь у славян, царство Аида у греков, Асгард у скандинавов, холмы сидов у кельтов, Дуат у египтян, Небеса у китайцев, Миктлан у ацтеков. На местах их держал <b>Алатырь</b> — бел-горюч камень в середине всех миров. Каждые врата вели в свою землю, и духи не путали дорог.":"精灵的世界向来不止一个——每个民族都有自己的：斯拉夫人的纳维、希腊人的冥府、北欧人的阿斯加德、凯尔特人的仙丘、埃及人的杜阿特、中国人的天界、阿兹特克人的米克特兰。把它们稳稳固定在原处的，是<b>阿拉特尔</b>——位于万界中心的白色燃石。每扇门都通往自己的土地，精灵们从不走错路。",
"Однажды осенней ночью Кощей Бессмертный решил спрятать свою смерть понадёжнее — прямо в сердце Алатыря. Камень треснул и раскололся. Все врата распахнулись разом, дороги между мирами спутались в клубок, и духи и боги семи мифологий высыпали в наш мир — каждый в своих краях. Эту ночь назвали <b>Перепутицей</b>. Кощей уверяет, что камень треснул сам, но Локи и Сунь Укун при этих словах почему-то хихикают.":"一个秋夜，不死者科谢伊想把自己的死亡藏得更稳妥些——就藏进阿拉特尔的心里。石头裂开，碎成了两半。所有的门同时敞开，万界之间的道路缠成了一团乱麻，七大神话的精灵和神明涌进我们的世界，各自落在自己的故土上。那一夜被称为<b>大纠缠</b>。科谢伊坚称石头是自己裂开的，可每当他这么说，洛基和孙悟空不知为何总在偷笑。",
"Теперь Гиппокамп плещется в фонтанах Рима, Леший гуляет по подмосковным паркам, а Ниссе греет котов в подъездах Осло: каждый дух живёт у себя на родине, и за чужими приходится шагать через Врата. Разломы — трещины от расколотого камня — открываются в каждом городе, а боги ставят святилища у себя на родине: Святилища — на Руси, Храмы — в Греции, Пагоды — в Китае, Пирамиды — в Америке. Город рождает и своих, новых духов: Вайфайку, Трамвайника, Фонарника.":"如今，海神驹在罗马的喷泉里戏水，列希在莫斯科郊外的公园里散步，尼瑟在奥斯陆的楼道里给猫咪取暖：每个精灵都生活在自己的故乡，想见别处的精灵，就得穿过大门。裂隙——碎石留下的裂缝——在每座城市里开启；神明们在各自的故乡建起圣所：圣所在罗斯，神殿在希腊，宝塔在中国，金字塔在美洲。城市还孕育出属于自己的新精灵：瓦伊法伊卡、特拉姆瓦伊尼克、福纳尔尼克。",
"Первыми с гостями поладили не учёные, а бабушки со своими оберегами: оказалось, оберег, сделанный с заботой, успокаивает любого духа, откуда бы тот ни был. Так появился <b>Орден Оберега</b> — союз Ловчих всех земель. Твоя задача — находить духов, ловить их оберегами, черпать силу из источников, закрывать разломы и собирать осколки Алатыря. Кто знает — может, однажды их хватит, чтобы распутать дороги домой.":"最先和这些来客相处融洽的，不是科学家，而是带着护符的老奶奶们：原来，用心做成的灵符能安抚任何精灵，无论它来自哪里。<b>护符修会</b>就这样诞生了——一个由各地捕灵师组成的联盟。你的任务是：寻找精灵，用灵符捕捉它们，从泉源汲取力量，关闭裂隙，收集阿拉特尔碎片。谁知道呢——也许有一天，碎片攒够了，就能解开回家的路。",
