"Первый дух":"第一只精灵",
"Твои духи":"你的精灵",
"Рядом появился дух — видишь светящийся круг на карте? <b>Коснись духа</b>, а потом <b>смахни оберег вверх</b>, прямо в него.":"附近出现了一只精灵——看到地图上发光的圆圈了吗？<b>点击精灵</b>，然后<b>把灵符往上滑</b>，直接扔向它。",
"Второй учебный дух рядом. Кольцо вокруг духа сжимается: бросай, когда оно <b>маленькое</b>, — выйдет «Отлично!». Зелёное кольцо — дух покладистый, красное — упрямый.":"第二只教学精灵就在附近。精灵周围的光圈会缩小：等它<b>变小</b>时投掷，就能打出“很棒！”。绿色光圈表示精灵温顺，红色表示倔强。",
"Это меню — здесь все разделы. Пока открыто не всё: разделы откроются по ходу обучения, подсвеченный — следующий.":"这是菜单——所有功能都在这里。目前还没有全部开放：各功能会在教程中逐步开放，高亮的是下一个。",
