"Это твоя коллекция — все пойманные духи. Сверху — сортировка по силе, новизне и имени и фильтр по стихиям.":"这是你的收藏——所有抓到的精灵。上方可以按战力、获得时间和名称排序，还能按元素筛选。",
"Это разделы Ордена. Открой <b>«Духи»</b> — там твоя коллекция.":"这些是修会的功能区。打开<b>“精灵”</b>——那里是你的收藏。",
"Это карточка духа: сила, стихия, приёмы и семейство. Ниже — кнопки «Усилить» и «Превратить», а ещё можно сделать духа спутником.":"这是精灵卡片：战力、元素、招式和家族。下方有“强化”和“进化”按钮，还能把精灵设为伙伴。",
"Коснись любого духа, чтобы открыть его <b>карточку</b>.":"点击任意一只精灵，打开它的<b>卡片</b>。",
"На карточке — сила духа. Нажми <b>«Усилить»</b>: за искры и эссенцию дух станет сильнее. Эссенцию приносят поимки духов того же семейства.":"卡片上显示精灵的战力。点<b>“强化”</b>：花费火花和精华，精灵就会变强。捕捉同一家族的精灵可获得精华。",
"Бестиарий — все виды духов. Пойманные видны целиком, встреченные — тенью. Коснись вида, чтобы прочитать о нём.":"图鉴收录所有种类的精灵。抓到的会完整显示，遇到过的只显示剪影。点击某个种类即可阅读介绍。",
"Теперь загляни в <b>«Бестиарий»</b> (меню) — там все виды духов. Сколько найдёшь ты?":"现在去看看<b>“图鉴”</b>（菜单）——里面有所有种类的精灵。你能找到多少呢？",
"Обереги пополняют <b>источники</b> — светящиеся чаши у памятников, фонтанов и храмов. Дойди до ближайшего джойстиком по <b>стрелке вверху</b> и коснись его. Если рядом нет — прогуляйся по карте.":"护符在<b>泉源</b>补充——泉源是纪念碑、喷泉和教堂旁发光的水盆。用摇杆跟着<b>上方的箭头</b>走到最近的泉源并点击它。附近没有的话，就在地图上走走。",
"Сумка: обереги, мёд, живая вода и ладан. Сверху видно, сколько ещё поместится; лишнее можно выбросить.":"背包：灵符、蜂蜜、生命之水和熏香。上方显示还能装多少；多余的可以丢掉。",
"Добыча уже в <b>Сумке</b>. Открой меню → «Сумка» и посмотри, что у тебя есть.":"战利品已经在<b>背包</b>里了。打开菜单 → “背包”，看看你都有什么。",
"Коконы греются шагами — одновременно можно греть три. Готовый кокон вылупится одним касанием. А твой первый дух идёт рядом — это спутник: в пути он находит эссенцию.":"茧靠步数来孵——最多同时孵三个。孵好的茧点一下就能孵化。你的第一只精灵会跟在你身边——它是你的伙伴，路上会找到精华。",
"Открой меню → <b>«Коконы»</b>. Первый кокон уже греется — пройди 2 км, и он вылупится.":"打开菜单 → <b>“茧”</b>。第一个茧已经在孵了——走2公里，它就会孵化。",
"Здесь задания дня — они обновляются в полночь. А источники иногда дают поручения: выполнишь — встретишь особого духа.":"这里是每日任务——每天午夜刷新。泉源有时还会给出委托：完成后就能遇到特别的精灵。",
"Открой <b>«Задания»</b> — там задания дня.":"打开<b>“任务”</b>——那里有每日任务。",
"Путь Ловчего: что откроется на каждом уровне и какие награды ждут. Звания растут: Послушник, Ловчий, Следопыт, Ведун, Хранитель.":"捕灵之路：每个等级会解锁什么、有哪些奖励。称号会随之提升：见习生、捕灵师、追踪者、智者、守护者。",
"И последнее: открой <b>«Путь»</b> в меню — там видно, что откроется на каждом уровне Ловчего.":"最后一步：在菜单中打开<b>“捕灵之路”</b>——可以看到捕灵师每个等级会解锁什么。",
