"Поражение":"失败",
"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"“等你变强了再来吧。”{0}说。换一支队伍试试：留意守护者的元素，把护盾留给它的招式。",
