"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"积分取决于对手：赢强者得分多，赢弱者得分少；输给弱者扣分更多。在你的联赛里赢同等对手+{0}，输−{1}；联赛越高，上升越慢。可能掉出当前联赛。联赛奖励每赛季发放一次。新赛季开始时，积分超过{2}的部分减半，上赛季最高联赛可得修会宝箱。在“{3}”、“{4}”和“{5}”联赛还有护身符。",
