"Спутник ходит с тобой и находит эссенцию своего семейства.":"伙伴会跟着你走，还会找到自己家族的精华。",
"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"联赛里对战的是真人捕灵师：赢强大的对手比赢弱小的对手得分更多。",
"Разломы открываются у Святилищ каждый час: собери команду из трёх духов.":"圣所旁每小时都会开启裂隙：组一支三只精灵的队伍吧。",
"Сияющие духи редки — их выдают искры вокруг.":"闪光精灵很稀有——周围的火花会暴露它们。",
"Коконы греются шагами: одновременно можно греть три.":"茧靠步数来孵：最多同时孵三个。",
"Ходи джойстиком: лёгкий наклон — шаг, до упора — бег. Километры для коконов считаются так же.":"用摇杆行走：轻推为步行，推到底为奔跑。孵茧的公里数照样计算。",
"Атлас мира переносит в любой уголок Земли раз в полчаса, а Врата Перепутицы — сразу.":"世界地图集每半小时可带你去地球任意角落，“大纠缠之门”则能立即传送。",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"每日任务在午夜刷新，完成全部三个还有每日宝箱。",
"Поставь защитника в Святилище своего клана — он принесёт искры.":"在自己战队的圣所派驻守卫——它会带来火花。",
