"Послушник":"见习生",
"Следопыт":"追踪者",
"Ведун":"智者",
"Поимка духов":"捕捉精灵",
"Обереги, мёд, источники и коконы":"灵符、蜂蜜、泉源和茧",
"Кампания, задания дня и поручения источников":"主线、每日任务和泉源委托",
"Лавка Ордена":"修会商店",
"Обереги, мёд и живая вода":"灵符、蜂蜜和生命之水",
"Коды дружбы и ежедневные подарки":"友谊码和每日礼物",
"Награды за обычную игру":"日常游玩的奖励",
"Бой командой из трёх духов с хранителем Разлома":"三只精灵组队对战裂隙守护者",
"Святилища предков":"祖先的圣所",
"Поединки 3 на 3 с хранителями":"与守护者3对3对决",
