"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"大纠缠搅乱了世界的道路，护符修会为捕灵师打开了传送门：在世界地图集中选择地球上的任意角落——你的狩猎将从那里开始。在地图上用摇杆行走，通过地图集前往新的地方。游戏不需要你手机的真实位置。进度保存在游戏服务器上，只有你能访问；服务器会检查每个操作，因此需要联网。所选区域的地图地点和天气来自 OpenStreetMap 和 Open-Meteo（天气可在设置中关闭）。",
