"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"绑定登录：菜单 → 设置 → 账号（Google、Yandex、VK、Telegram或邮箱）。否则游客进度将无法转移。",
